import React, { useState, useEffect } from 'react';
import API from '../../services/api';
import './Profile.css';

const Profile = () => {
  const [profileData, setProfileData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState({});

  useEffect(() => {
    const fetchProfile = async () => {
      const userId = localStorage.getItem('userId');
      if (!userId) {
        setLoading(false);
        return;
      }

      try {
        const response = await API.get(`/profile/${userId}`);
        setProfileData(response.data.settings);
      } catch (err) {
        console.error('Failed to fetch profile:', err);
        // Fallback to localStorage data
        const savedProfile = localStorage.getItem("uaps-profile");
        if (savedProfile) {
          const parsed = JSON.parse(savedProfile);
          setProfileData(parsed.settings); // make sure backend and localStorage structure match
        } else {
          // optional fallback to registerName/Number
          const name = localStorage.getItem('registerName') || 'N/A';
          const number = localStorage.getItem('registerNumber') || 'N/A';
          setProfileData({
            firstName: name.split(' ')[0] || name,
            lastName: name.split(' ').slice(1).join(' ') || '',
            address: 'N/A',
            number: number,
            dateOfBirth: 'N/A'
          });
        }

      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, []);

  const handleEdit = () => {
    setEditData({ ...profileData });
    setIsEditing(true);
  };

  const handleSave = async () => {
    const userId = localStorage.getItem('userId');
    if (!userId) return;

    try {
      await API.put(`/profile/${userId}`, editData);
      setProfileData(editData);
    } catch (err) {
      console.error('Failed to update profile:', err);
      // fallback to localStorage
    } finally {
      setIsEditing(false);
      // Save to localStorage for live preview
      localStorage.setItem('uaps-profile', JSON.stringify({ settings: editData }));
    }
  };


  const handleCancel = () => {
    setEditData(profileData);
    setIsEditing(false);
  };

/* global chrome */
const handleExport = () => {
  const exportData = {
    settings: {
      textSize: profileData.textSize || 'Medium',
      toggles: profileData.toggles || {}
    }
  };

  // Only try to sync to Chrome extension if running inside Chrome extension
  if (window.chrome && chrome.storage && chrome.storage.sync) {
    chrome.storage.sync.set({ uapsProfile: exportData }, () => {
      console.log('Profile synced to Chrome extension');
    });
  } else {
    console.warn('Chrome storage not available. You are not running inside the extension.');
  }

  // Always allow local download for testing
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
  const link = document.createElement('a');
  link.setAttribute('href', dataStr);
  link.setAttribute('download', 'uaps-profile.json');
  link.click();
};







  if (loading) {
    return (
      <div className="content-area">
        <div className="loading-container">
          <div className="loading-spinner"></div>
          Loading profile...
        </div>
      </div>
    );
  }

  if (!profileData) {
    return <div className="content-area">No profile data found.</div>;
  }

  return (
    <div className="content-area">

      {/* HEADER SA TAAS – ICON LANG */}
      <div className="top-header-icon-only">
        <div className="header-avatar">👤</div>
      </div>

      {/* EXISTING PROFILE CARD WRAPPED WITH FRAME */}
      <div className="profile-frame">
        <div className="profile-container">
          <div className="profile-header-card">
            <div className="avatar-circle">👤</div>
            <button className="edit-btn" onClick={handleEdit}>🖊️ Edit Profile</button>
          </div>

          <div className="profile-details-card">
            <h2>{profileData.firstName} {profileData.lastName}</h2>

            <div className="details-box">
              <h3 className="box-title">Profile details</h3>

              <div className="details-grid">
                <div className="detail-item">
                  <span className="icon">👤</span>
                  <div>
                    <label>First Name</label>
                    {isEditing ? (
                      <input
                        type="text"
                        value={editData.firstName || ''}
                        onChange={(e) => setEditData({ ...editData, firstName: e.target.value })}
                      />
                    ) : (
                      <p>{profileData.firstName}</p>
                    )}
                  </div>
                </div>

                <div className="detail-item">
                  <span className="icon">👤</span>
                  <div>
                    <label>Last Name</label>
                    {isEditing ? (
                      <input
                        type="text"
                        value={editData.lastName || ''}
                        onChange={(e) => setEditData({ ...editData, lastName: e.target.value })}
                      />
                    ) : (
                      <p>{profileData.lastName}</p>
                    )}
                  </div>
                </div>

                <div className="detail-item">
                  <span className="icon">📞</span>
                  <div>
                    <label>Number</label>
                    {isEditing ? (
                      <input
                        type="tel"
                        value={editData.number || ''}
                        onChange={(e) => setEditData({ ...editData, number: e.target.value })}
                      />
                    ) : (
                      <p>{profileData.number}</p>
                    )}
                  </div>
                </div>

                <div className="detail-item">
                  <span className="icon">📍</span>
                  <div>
                    <label>Address</label>
                    {isEditing ? (
                      <input
                        type="text"
                        value={editData.address || ''}
                        onChange={(e) => setEditData({ ...editData, address: e.target.value })}
                      />
                    ) : (
                      <p>{profileData.address}</p>
                    )}
                  </div>
                </div>

                <div className="detail-item">
                  <span className="icon">📅</span>
                  <div>
                    <label>Date of Birth</label>
                    {isEditing ? (
                      <input
                        type="date"
                        value={editData.dateOfBirth || ''}
                        onChange={(e) => setEditData({ ...editData, dateOfBirth: e.target.value })}
                      />
                    ) : (
                      <p>{profileData.dateOfBirth || 'N/A'}</p>
                    )}
                  </div>
                </div>
              </div>

            </div>

            {isEditing && (
              <div className="edit-buttons">
                <button onClick={handleSave}>Save</button>
                <button onClick={handleCancel}>Cancel</button>
              </div>
            )}

            <div className="export-section">
              <button onClick={handleExport}>
                Sync Profile to Chrome Extension
              </button>

            </div>
          </div>
        </div>
      </div>

    </div>
  );
};

export default Profile;
